ACM/算法/数论/斯特林数,欧拉数.content:
第一类斯科特数

第一类斯科特数 c(n,k) 表示 将n个不同元素排列成恰好k个”循环”的排列数

对于循环,我们可以理解为\{1,2,3\}与\{2,3,1\} 与\{3,2,1\}均为一类循环,因为将这些数无限写下去的形式上是一致的
\{\cdots,\textcolor{blue}{1,2,3},1,\textcolor{red}{2,3,1},2,\textcolor{green}{3,1,2},\cdots\}
例子

c(3,1) = 2,即所有3!排列都在一个大循环中,此时有两种方案{(1,2,3),(1,3,2)}
c(3,2) = 3,此时有 (1)(2,3) | (2)(1,3) | (3)(1,2) 这样的组合方式
c(3,3) = 1,此时每个元素各自组成一个循环

第一类斯科特数递推公式
c(n,k) = c(n - 1,k -1 ) + (n - 1)\cdot c(n-1,k)
其中递推的初始条件我们规定为

c(0,0) = 1 \text{ , } c(n,0) = 0(n &gt; 0) \text{ , }c(0,k) = 0(k&gt;0)

上面为无符号第一类斯科特数的递归方式 如果想获得有符号类的可以使用 s(n,k) = (-1)^{n-k}c(n,k)方式得到
应用:

在排列的循环结构或者有向图的环的计数中使用
在阶乘多项式展开中使用

x^{\underline{n}} = x(x-1)\cdots(x-n+1) = \sum\limits^{n}_{k=0}s(n,k)s^k

其中 s(n,k)即有符号的第一类斯科特数

第二类斯科特数

第二类斯科特数 S(n,k) 表示将 n 个不同元素划分为恰好 k 个非空无序集合的方案数

对与三个不同元素{1,2,3}划分

S(3,1) = 1 ,即所有元素处于一个集合中
S(3,2) = 3:

\{\{1\},\{2,3\}\},\{\{2\},\{1,3\}\},\{\{3\},\{1,2\}\}



对第二类斯特林数有递推公式
S(n,k) = S(n-1,k-1) + k\cdot S(n-1,k) 

初始条件我们规定
S(0,0) = 1 \text{ , } S(n,0) = 0(n &gt; 0) \text{ , }S(0,k) = 0(k&gt;0)

对与第二类斯特林数,我们有显式公式:
S(n,k) = \frac{1}{k!} \sum_{i=0}^{k} (-1)^i \binom{k}{i} (k-i)^n
可以在O(k)复杂度下计算出其值,可以结合快速组合数与快速幂计算,在最后给出板子
第一类欧拉数
i64 ksm(i64 a, i64 b, i64 mod = MOD)
{
    i64 res = 1;
    while (b) {
        if (b &amp; 1) res = res * a % mod;
        a = a * a % mod;
        b &gt;&gt;= 1;
    }
    return res;
}

struct Stirling
{
    vector&lt;i64&gt; fac, inv_fac;
    i64 MAX_N;
    Stirling(i64 MAXK)
    {
        MAX_N = MAXK;
        fac.resize(MAX_N);
        inv_fac.resize(MAX_N);
        init();
    }
    // 预处理 [0, MOD-1] 阶乘及逆元
    void init()
    {
        fac[0] = 1;
        for (i64 i = 1; i &lt; MAX_N; i++) fac[i] = fac[i - 1] * i % MOD;
        inv_fac[MAX_N - 1] = ksm(fac[MAX_N - 1], MOD - 2);
        for (i64 i = MAX_N - 2; i &gt;= 0; i--) inv_fac[i] = inv_fac[i + 1] * (i + 1) % MOD;
    }
    // 计算 C(n, k) mod MOD，要求 n, k &lt; MOD
    inline i64 C_small(i64 n, i64 k)
    {
        if (k &lt; 0 || k &gt; n) return 0;
        return fac[n] * inv_fac[k] % MOD * inv_fac[n - k] % MOD;
    }
    // Lucas 定理递归求解大组合数
    i64 C(i64 n, i64 k)
    {
        if (k &lt; 0 || k &gt; n) return 0;
        if (n &lt; MOD &amp;&amp; k &lt; MOD) return C_small(n, k);
        return C(n / MOD, k / MOD) * C_small(n % MOD, k % MOD) % MOD;
    }
    i64 A(int n, int k) const
    {
        if (k &lt; 0 || k &gt; n) return 0;
        return fac[n] * inv_fac[n - k];
    }
    // 第二类斯特林数的显式表示
    i64 get_Stirling(int n, int k)
    {
        if (k &lt; 0 || k &gt; n) return 0;
        i64 res = 0;
        for (int i = 0; i &lt;= k; ++i) {
            i64 term = C(k, i) * ksm(k - i, n) % MOD;
            // 符号： (-1)^i，根据公式 S(n,k) = 1/k! * sum_{i=0..k} (-1)^i C(k,i) (k-i)^n
            if (i &amp; 1)
                res = (res - term + MOD) % MOD;
            else
                res = (res + term) % MOD;
        }
        res = res * inv_fac[k] % MOD; // 除以 k!
        return res;
    }
    // 第二类欧拉数计算
    i64 sec_Eulr(int n, int k)
    {
        return (get_Stirling(n, k) * fac[k]) % MOD;
    }
};

其实就是在快速组合数上进行了添加

ACM/算法/数论/约数.content:
约数个数和定理
我们记 d(i) 为 数 i 的约数个数,存在等式
\sum\limits^{n}_{i = 1}d(i) = \sum\limits^{n}_{i = 1}\left\lfloor \frac{n}{i} \right\rfloor
这个等式的证明如下
记二重计数集合 S = \{(a,b) \in \mathbb{Z}{}^{2}_{\geq1}: ab \leq n\}
含义为两个大于1的正整数a,b其乘积小于等于n我们需要得知的即为|S|
按积分组角度
对于每一个i \in [1,n],将所有满足 ab = i的有序对计入S,这个有序对个数正好就是d(i),将i = 1到n累加有:
|S| = \sum\limits^{n}_{i=1}d(i) \tag{1}
按固定的a 角度
固定a \in [1,n],则满足条件的b的个数是满足 ab \leq n的个数,即:
\{b | b \geq1 \text{ and } b \leq \frac{n}{a}\} = \left\lfloor \frac{n}{a} \right\rfloor 
累加有:
|S| = \sum\limits^{n}_{a=1} \left\lfloor \frac{n}{a} \right\rfloor \tag{2}
而这两个计数的是同一个集合,结合(1),(2)可证
\boxed{\sum\limits^{n}_{i = 1}d(i) = \sum\limits^{n}_{i = 1}\left\lfloor \frac{n}{i} \right\rfloor}



                  Tip




在具体计算的时候有时由于 n 过大,我们还需要将算法复杂度从 O(n) 降低到 O(\sqrt{n}),具体操作可以使用 整除分块



Solution1
void solve()
{
    i64 n;
    cin &gt;&gt; n;
    i64 ans = 0;
    // 注意for中 l 应该是 跳入到下一个块中
    for (i64 l = 1, r; l &lt;= n; l = r + 1) {
        // 当前一个区间的整除数
        i64 k = n / l;
        // 计算块右边界
        r = n / k;
        // 计算结果(不要忘记块长)
        ans += k * (r - l + 1);
    }
    cout &lt;&lt; ans &lt;&lt; endl;
}

ACM/算法/最长回文子序列.content:
最长回文子序列

给定一个字符串 s , 求 s 的最长回文子序列

1 模拟暴力法

通过一个二维数组遍历原字符串的所有子串
逐一判断该子串是否为回文串
更新最长子串

#pragma GCC optimize(3)
#include &lt;bits/stdc++.h&gt;
//#define int LL
#define endl &#039;\n&#039;
#define size_t int
#define all(v) v.begin(), v.end()
using namespace std;
typedef long long LL;
typedef vector&lt;int&gt; vint;
typedef vector&lt;vint&gt; vvint;
typedef vector&lt;string&gt; vstr;
typedef pair&lt;int, int&gt; pii;
typedef vector&lt;pii&gt; vpii;

string huiwen(const string &amp;s, int back, int front)
{
    int idx_b = back;
    int idx_f = front;
    while (idx_b &gt; idx_f) {
        if (s[idx_f] != s[idx_b]) {
            return s.substr(0,1);
        }
        idx_f++;
        idx_b--;
    }
    string res;
    for (size_t i = front; i &lt;= back; i++) {
        res += s[i];
    }
    return res;
}

signed main()
{
    //ios::sync_with_stdio(0),cin.tie(0),cout.tie(0);
    string s;
    cin &gt;&gt; s;
    string ans = &quot;&quot;;
    if(s.size() &lt;= 1){
        cout &lt;&lt; s;
    }
    for (size_t i = 0; i &lt; s.size(); i++) {
        for (size_t j = i + 1; j &lt; s.size(); j++) {
            string temp = huiwen(s, j, i);
            ans = (temp.size() &gt; ans.size() ? temp : ans);
        }
    }
    cout &lt;&lt; ans;
    return 0;
}

这个算法的复杂度来到了惊人的O(n^3),令人汗颜，数据量在10^3就能直接让OJ爆TLE

2 中心扩展算法
中心算法的三个核心步骤

1.选择中心：对于一个长度为 n 的字符串，其拥有  2n - 1 个中心结点（即长度为奇数的回文子串结点有n个，长度为偶数的回文子串的结点有n-1个
2.扩展回文：对于每个选定的中心，尝试向两边扩展，直到无法形成回文为止
3.更新结果：在每次成功扩展后，计算当前回文的长度，并与已知的最大回文长度进行比较。如果更长，则更新最大回文及其起始位置

//#pragma GCC optimize(3)
#include &lt;bits/stdc++.h&gt;
//#define int LL
#define endl &#039;\n&#039;
#define size_t int
#define all(v) v.begin(), v.end()
using namespace std;
typedef long long LL;
typedef vector&lt;int&gt; vint;
typedef vector&lt;vint&gt; vvint;
typedef vector&lt;string&gt; vstr;
typedef pair&lt;int, int&gt; pii;
typedef vector&lt;pii&gt; vpii;

int expandAroundCenter(const string &amp;s, int left, int right)
{
    while (left &gt;= 0 &amp;&amp; right &lt; s.size() &amp;&amp; s[left] == s[right]) {
        left--;
        right++;
    }
    return right - left - 1;
}

string longestPalindrome(const string &amp;s)
{
    if (s.empty()) return &quot;&quot;;
    int start = 0;
    int end = 0;
    for (size_t i = 0; i &lt; s.size(); i++) {
        int len1 = expandAroundCenter(s, i, i);
        int len2 = expandAroundCenter(s, i, i + 1);
        int len = max(len1, len2);
        if (len &gt; end - start) {
            end = i + len / 2;
            start = i - (len - 1) / 2;
        }
    }
    return s.substr(start, end - start + 1);
}

signed main()
{
    //ios::sync_with_stdio(0),cin.tie(0),cout.tie(0);
    string s;
    cin &gt;&gt; s;
    cout &lt;&lt; longestPalindrome(s) &lt;&lt; endl;
    return 0;
}

此时时间复杂度已经降至 O(n^2) ，空间复杂度降低至O(1) ,已经绝杀大部分算法

3 Manacher’s Algorithm

很抱歉没能让manacher大人尽兴	——by 中心扩展算法



Manacher’s Algorithm(马拉车算法)是一种高效解决最长回文子串的算法，其提供一个O(n)复杂度下的方法来实现对回文子序列的查找

核心思想
回文串的对称性： 假设已经计算出了以某个位置为中心的回文串的半径（即该回文串两边的最大扩展长度），那么与其对称的部分的回文半径也可以直接推算出来
预处理：将原字符串进行预处理，以避免处理奇数长度和偶数长度回文的不同情况。通常的做法是在每个字符之间插入一个特殊字符（如 #），并在字符串的开头和结尾添加不同的特殊字符（如 ^ 和 $）。这样处理后的字符串长度一定是奇数，且不会出现冲突。
动态维护最远回文边界：在扩展时，维护一个“右边界” R 和一个“中心” C，C 代表回文串的中心位置，R 代表回文串的最右边界。当当前处理的位置 i 位于 R 的范围内时，可以利用已知的对称性质来减少计算。

//#pragma GCC optimize(3)
#include &lt;bits/stdc++.h&gt;
//#define int LL
#define endl &#039;\n&#039;
#define size_t int
#define all(v) v.begin(), v.end()
using namespace std;
typedef long long LL;
typedef vector&lt;int&gt; vint;
typedef vector&lt;vint&gt; vvint;
typedef vector&lt;string&gt; vstr;
typedef pair&lt;int, int&gt; pii;
typedef vector&lt;pii&gt; vpii;

//预处理
string preprocess(const string &amp;s)
{
    string t = &quot;^&quot;;
    for (char c : s) {
        t += &quot;#&quot; + string(1, c);
    }
    t += &quot;#$&quot;;
    return t;
}

string longestPalindrome(const string &amp;s)
{
    string T = preprocess(s);
    int n = T.size();
    vector&lt;int&gt; P(n, 0); //P[i] 记录以 t[i] 为中心的回文半径
    int C = 0, R = 0;    //C 是回文中心，R 是回文串的最右边界
    for (size_t i = 1; i &lt; n - 1; i++) {
        // 确定对称位置
        int Mirror = 2 * C - i;
        if (i &lt; R) {
            P[i] = min(P[Mirror], R - i);
        }
        // 尝试扩展边界
        while (T[i + 1 + P[i]] == T[i - 1 - P[i]]) {
            P[i]++;
        }
        // 如果当前回文串扩展超过了 R，更新中心和右边界
        if (i + P[i] &gt; R) {
            C = i;
            R = i + P[i];
        }
    }
    // 找到最长的回文子串
    int maxLen = 0;
    int Centerindex = 0;
    for (size_t i = 0; i &lt; n - 1; i++) {
        if (P[i] &gt; maxLen) {
            maxLen = P[i];
            Centerindex = i;
        }
    }
    // 构造回文串
    int start = (Centerindex - maxLen) / 2;
    return s.substr(start, maxLen);
}

signed main()
{
    //ios::sync_with_stdio(0),cin.tie(0),cout.tie(0);
    string s;
    cin &gt;&gt; s;
    cout &lt;&lt; longestPalindrome(s) &lt;&lt; endl;
    return 0;
}

