#include &lt;bits/stdc++.h&gt;
using namespace std;

typedef long long ll;
typedef pair&lt;ll, ll&gt; pii;

signed main()
{
    int T = 1;
    cin &gt;&gt; T;
    vector&lt;pii&gt; food(T);
    for (auto &amp;&amp;[s, k] : food) {
        cin &gt;&gt; s &gt;&gt; k;
    }
    // 使用集合记录所有可能的 (酸度, 苦度) 组合
    set&lt;pii&gt; dp;
    dp.emplace(1, 0); // 初始状态
    for(auto &amp;[s, b] : food){
        set&lt;pii&gt; temp = dp;
        for(auto &amp;[acid, bitter] : dp){
            temp.emplace(acid * s, bitter + b);
        }
        dp = move(temp);
    }
    // gtp写的，确实很精巧，用set记录了每个可能的情况
    // 因为初始状况是(1,0),就相当于每一次内层循环的第一次都是只选当前组的食物
    // 每一次都会把dp数组过完一遍，相当于在之前的所有情况下加一个 选择当前食物的情况
    ll result = LLONG_MAX;
    for(auto &amp;[acid, bitter] : dp){
        if(acid != 1 || bitter != 0){
            result = min(result, abs(acid - bitter));
        }
    }
    cout &lt;&lt; result;
    return 0;
}

ACM/算法/素数筛.content:
9 素数筛
9.1 一般双重筛

通过不断试除来判断某一数字k有无因数
时间复杂度为O(N^2)

bool prime(long long i)
{
    if (i == 2)
        return 1;
    else if (i == 1)
        return 0;
    for (size_t k = 2; k * k &lt;= i; k++) {
        if (i % k == 0) {
            return 0;
        }
    }
    return 1;
}
int main()
{
    long long n;
    cin &gt;&gt; n;
    for (size_t i = 2; i &lt;= n; i++) {
        if (prime(i)) {
            cout &lt;&lt; i &lt;&lt; endl;
        }
    }
    return 0;
}
9.2 埃拉托斯特尼筛法

核心思路是先标记素数，然后把素数的所有倍数全标记为非素数
时间复杂度是O(n\log{\log{n}})
对于任意一个大于1的正整数n,那么它的x倍就是合数(x &gt; 1)。利用这个结论，我们可以避免很多次不必要的检测。
如果我们从小到大考虑每个数，然后同时把当前这个数的所有（比自己大的）倍数记为合数，那么运行结束的时候没有被标记的数就是素数了。

vector&lt;int&gt; prime;
vector&lt;bool&gt; IsPrime(1e7);

void Eratosthenes(long long n)
{
    IsPrime[0] = IsPrime[1] = 0; //前两项不为素数，记作0
    for (size_t i = 2; i &lt;= n; i++) //先全部记作1
    {
        IsPrime[i] = 1;
    }
    //memset(IsPrime,1,sizeof(IsPrime)); //似乎使用memset的时间复杂度也是O(N)
    for (size_t i = 2; i &lt;= n; i++)
    {
        //素数筛选
        //从第三项开始，如果这个数被标记为1，就把它记作素数，放入数组 
        //同时从 i*i 项开始，每次将 i 的倍数标记为非素数
        if (IsPrime[i])
        {
            prime.push_back(i);
            if ((long long)i * i &gt; n) continue; //超过n的不计
            for (size_t j = i*i ; j &lt;= n; j += i)
            {
                IsPrime[j] = 0;
            }
        }
    }
}

int main()
{
    long long n;
    cin &gt;&gt; n;
    Eratosthenes(n);
    for (auto &amp;&amp;i : prime) cout &lt;&lt; i &lt;&lt;endl;
    return 0;
}

我们可以只筛选到\sqrt{N}来降低操作次数

#include &lt;bits/stdc++.h&gt;
#define endl &quot;\n&quot;
using namespace std;

vector&lt;int&gt; prime;
vector&lt;bool&gt; IsPrime(1e7);

void Eratosthenes(long long n)
{
    IsPrime[0] = IsPrime[1] = 0; //前两项不为素数，记作0
    for (size_t i = 2; i &lt;= n; i++) //先全部记作1
    {
        IsPrime[i] = 1;
    }
    //memset(IsPrime,1,sizeof(IsPrime)); //似乎使用memset的时间复杂度也是O(N)
    for (size_t i = 2; i*i &lt;= n; i++)
    {
        //素数筛选
        //从 i*i 项开始，每次将 i 的倍数标记为非素数
        if (IsPrime[i])
        {
            for (size_t j = i*i ; j &lt;= n; j += i)
            {
                IsPrime[j] = 0;
            }
        }
    }
    //计入数组
    for (size_t i = 2; i &lt;= n; i++)
    {
        if (IsPrime[i])
        {
            prime.push_back(i);
        }
    }
}

int main()
{
    long long n;
    cin &gt;&gt; n;
    Eratosthenes(n);
    for (auto &amp;&amp;i : prime) cout &lt;&lt; i &lt;&lt;endl;
    return 0;
}

我们也可以改写0/1来实现非初始化bool数组

#include &lt;bits/stdc++.h&gt;
#define endl &quot;\n&quot;
using namespace std;

vector&lt;int&gt; prime;
vector&lt;bool&gt; IsPrime(1e7);

void Eratosthenes(long long n)
{
    IsPrime[0] = IsPrime[1] = 0; //前两项不为素数，记作0
    for (size_t i = 2; i*i &lt;= n; i++)
    {
        //素数筛选
        //从 i*i 项开始，每次将 i 的倍数标记为非素数
        if (!IsPrime[i])
        {
            for (size_t j = i*i ; j &lt;= n; j += i)
            {
                IsPrime[j] = 1;
            }
        }
    }
    //计入数组
    for (size_t i = 2; i &lt;= n; i++)
    {
        if (!IsPrime[i])
        {
            prime.push_back(i);
        }
    }
}

int main()
{
    long long n;
    cin &gt;&gt; n;
    Eratosthenes(n);
    for (auto &amp;&amp;i : prime) cout &lt;&lt; i &lt;&lt;endl;
    return 0;
}
9.3 欧拉筛法

时间复杂度O(n)
埃氏筛法仍有优化空间，它会将一个合数重复多次标记。我们可以用改进的筛法欧拉筛来计算

#include &lt;bits/stdc++.h&gt;
#define endl &quot;\n&quot;
using namespace std;

vector&lt;int&gt; prime;
vector&lt;bool&gt; not_prime(1e7);

void Euler(long long &amp;n)
{
    for (size_t i = 2; i &lt;= n; i++)
    {
        //如果该数标记为 0 即 非(非素数),计入素数数组
        if (!not_prime[i])
        {
            prime.push_back(i);
        }
        // 换言之，i 之前被 prime[j] 筛过了
        // 由于 prime 里面质数是从小到大的，所以 i 乘上其他的质数的结果一定会被
        // prime[j] 的倍数筛掉，就不需要在这里先筛一次，所以这里直接 break掉
        for (auto &amp;&amp;j : prime)
        {
            if(i*j &gt; n) break;
            not_prime[i*j] = 1;
            if(i%j == 0) break;
        }
    }
}

int main()
{
    long long n;
    cin &gt;&gt; n;
    Euler(n);
    for (auto &amp;&amp;i : prime) cout &lt;&lt; i &lt;&lt; endl;
    return 0;
}

ACM/算法/约瑟夫问题.content:
约瑟夫问题

人们站在一个等待被处决的圈子里。 计数从圆圈中的指定点开始，并沿指定方向围绕圆圈进行。 在跳过指定数量的人之后，处刑下一个人。 对剩下的人重复该过程，从下一个人开始，朝同一方向跳过相同数量的人，直到只剩下一个人，并被释放。
现在我想知道幸存者的编号(编号从0开始)的多少




                  Tip




考虑在有n - 1个人，处决k的情况下最后一个人的编号是f(n - 1,k),那么对n个人而言，有递推式==f(n,k) = (f(n-1,k) + k)\mod n==
递推式求解抽象化：考虑对f(n-1,k)，扩展到n人时，我们只需要将第k个人处决，问题便又回到了对n-1人中找f(n-1,k)的问题上，但我们删除编号k个数时候,所有数的编号都会进行变化映射,即新的环的起点发生了变化,即集体向后移动k位且保证在n范围内,所以需要取模与n
即 : ==f(n,k) = (f(n-1,k) + k)\mod n==



int josephus(int n, int k)
{
    int s = 0;
    for (int i = 2; i &lt;= n; i++) s = (s + k) % i;
    return s + 1;
}

上述算法时间复杂度O(n),空间复杂度O(1),但对 k = 2的情况我们可以有特殊解法使时间复杂度降低到O(\log n) : 引用自Wikipedia

答案的最漂亮的形式，与n的二进制表示有关：把n的第一位移动到最后，便得到f(n)。如果n的二进制表示为n=b_{0}b_{1}b_{2}b_{3}\dots b_{m}则f(n)=b_{1}b_{2}b_{3}\dots b_{m}b_{0}。这可以通过把n表示为2^{m}+l来证明。


int yuesefu(int n)
{
    // 找到最高位的值，即n的最高位所代表的2的幂
    int highestBit = 1;
    while (highestBit &lt;= n) {
        highestBit &lt;&lt;= 1; // 将最高位左移
    }
    // 移动后的结果
    return (n - (highestBit &gt;&gt; 1)) &lt;&lt; 1 + 1;
 // return (n -  highestBit / 2) * 2 + 1
}

ACM/算法/线性丢番图方程.content:
20 线性丢潘图方程(Diophantine equation)

线性丢番图方程（Diophantine equation）通常指的是形如 ax+by=c的方程，其中 a,b,c 是整数，而我们感兴趣的是找到整数解 x,y。
孩子们，牛客周赛77第三题会这个秒杀了（怪不得那群人可以20min ak，全是板子题）

x,y 存在解的情况下，a,b 满足以下条件

c 必须是 a 和 b 的最大公约数 (gcd) 的倍数

具体而言，当 c\mod({\gcd(a,b)}) = 0 时存在x,y 使上述方程存在整数解

扩展：
若上述条件满足，则存在无穷多组解 (x,y) ,一旦找到一组特殊的解(x_0,y_0)，则所有解都可以被表示出来，其表示方式如下
x = x_0 + k\left(\frac{b}{g}\right)
y = y_0 - k\left(\frac{a}{g}\right)
其中g = \gcd(a,b)


其具体作用为，在确定线性丢潘图方程有解的情况，可以使用扩展欧几里得算法展欧几里得算法找出其中一个特解(x_0,y_0) , 然后找出所有解的通项

找出丢潘图方程通项代码模板

需要用到扩展欧几里得算法进行实现


如下：

#include &lt;bits/stdc++.h&gt;
using namespace std;

// 扩展欧几里得算法
int exgcd(int a, int b, int &amp;x, int &amp;y)
{
    if (b == 0) {
        x = 1;
        y = 0;
        return a; // 返回gcd(a, b)
    }
    int r = exgcd(b, a % b, x, y);
    int t = y;
    y = x - (a / b) * y;
    x = t;
    return r;
}

int main()
{
    int a, b, c;
    cout &lt;&lt; &quot;请输入线性丢番图方程(ax+by=c)的系数a, b和常数c : &quot; &lt;&lt; endl;
    cin &gt;&gt; a &gt;&gt; b &gt;&gt; c;
    int g = __gcd(a, b); // 计算gcd(a, b)
    if (c % g != 0) {
        cout &lt;&lt; &quot;方程无整数解.&quot; &lt;&lt; endl;
        return 0;
    }
    // 使用扩展欧几里得算法找到一个特解
    int x0, y0;
    exgcd(a / g, b / g, x0, y0);
    x0 *= c / g;
    y0 *= c / g;
    cout &lt;&lt; &quot;一个特解为: x = &quot; &lt;&lt; x0 &lt;&lt; &quot;, y = &quot; &lt;&lt; y0 &lt;&lt; endl;
    // 输出一般解
    cout &lt;&lt; &quot;一般解的形式为:&quot; &lt;&lt; endl;
    cout &lt;&lt; &quot;x = &quot; &lt;&lt; x0 &lt;&lt; &quot; + &quot; &lt;&lt; b / g &lt;&lt; &quot; * k&quot; &lt;&lt; endl;
    cout &lt;&lt; &quot;y = &quot; &lt;&lt; y0 &lt;&lt; &quot; - &quot; &lt;&lt; a / g &lt;&lt; &quot; * k&quot; &lt;&lt; endl;
    cout &lt;&lt; &quot;其中k为任意整数.&quot; &lt;&lt; endl;
    return 0;
}



                  Tip




由于 g 已经是 a 和 b 的最大公约数，因此 \frac{a}{g} 和 \frac{b}{g} 互质（即它们的最大公约数为1）。这样做的目的是为了简化问题，使得新的系数 \frac{a}{g} 和 \frac{b}{g} 成为互质的整数，从而可以使用扩展欧几里得算法来求解简化后的方程。
因为有了简化过程，所以结果出来时要乘上 \frac{c}{g}来回复正常解

ACM/算法/线段树Seg/支持动态修改的线段树.content:
动态修改
作为一颗线段树，如果它只能查询而不能修改，就很容易被上位替代，而支持在O(\log n) 下进行区间修改和区间查询，则是线段树最大的优势
要实现区间修改，我们需要引入 lazy propagation即懒标记
懒标记的作用我们用如下例子表示：

假设我们需要对区间 [2,5] 的元素都+10，且当前节点[1,8] 覆盖了 [2,5]
我们可以：

不立即递归更新子节点
在当前节点打上懒标记
记录这个区间整体应该要+10
只有当 下次访问到这个区间的子节点的时，才下传这个标记


变化
和支持区间查询的线段树的线段树相比，我们的结构体的存储信息应该多加上懒标记的信息
同时我们需要多加一些函数来应用和下传懒标记，以及区间修改
我们这次以支持模下运算的加法和乘法演示
struct Seg
{
    struct Node
    {
        i64 sum = 0, add = 0, mul = 1;
    };
    i64 n;
    i64 mod;
    vector&lt;Node&gt; seg;
    Seg(i64 n, i64 mod)
    {
        this-&gt;n = n;
        this-&gt;mod = mod;
        seg.resize((n &lt;&lt; 2) + 4);
    }
    // 合并逻辑
    Node merge(const Node &amp;L, const Node &amp;R)
    {
        Node res;
        res.sum = (L.sum + R.sum) % mod;
        res.add = 0;
        res.mul = 1;
        return res;
    }
    //懒标记应用
    void applyadd(i64 idx, i64 l, i64 r, i64 val)
    {
        seg[idx].add = (seg[idx].add + val) % mod;
        seg[idx].sum = (seg[idx].sum + val * (r - l + 1) % mod) % mod;
    }
    void applymul(i64 idx, i64 l, i64 r, i64 val)
    {
        seg[idx].mul = (seg[idx].mul * val) % mod;
        seg[idx].sum = seg[idx].sum * val % mod;
        seg[idx].add = seg[idx].add * val % mod;
    }
    // 懒标记向下应用
    void push(i64 idx, i64 l, i64 r)
    {
        i64 &amp;_add = seg[idx].add;
        i64 &amp;_mul = seg[idx].mul;
        if (_add == 0 &amp;&amp; _mul == 1) return;
        i64 mid = (l + r) &gt;&gt; 1;
        applymul(idx &lt;&lt; 1, l, mid, _mul);
        applymul(idx &lt;&lt; 1 | 1, mid + 1, r, _mul);
        applyadd(idx &lt;&lt; 1, l, mid, _add);
        applyadd(idx &lt;&lt; 1 | 1, mid + 1, r, _add);
        _add = 0;
        _mul = 1;
    }
    void build(i64 idx, i64 l, i64 r, const vint &amp;a)
    {
        if (l == r) {
            seg[idx].sum = a[l];
            seg[idx].add = 0;
            return;
        }
        i64 mid = (l + r) &gt;&gt; 1;
        build(idx &lt;&lt; 1, l, mid, a);
        build(idx &lt;&lt; 1 | 1, mid + 1, r, a);
        seg[idx] = merge(seg[idx &lt;&lt; 1], seg[idx &lt;&lt; 1 | 1]);
    }
    // 1是加法，2是乘法
    void update(i64 idx, i64 l, i64 r, i64 ql, i64 qr, i64 val, i64 op)
    {
        if (op == 1) {
            if (ql &lt;= l &amp;&amp; r &lt;= qr) {
                applyadd(idx, l, r, val);
                return;
            }
        }
        if (op == 2) {
            if (ql &lt;= l &amp;&amp; r &lt;= qr) {
                applymul(idx, l, r, val);
                return;
            }
        }
        push(idx, l, r);
        i64 mid = (l + r) &gt;&gt; 1;
        if (ql &lt;= mid) update(idx &lt;&lt; 1, l, mid, ql, qr, val, op);
        if (qr &gt; mid) update(idx &lt;&lt; 1 | 1, mid + 1, r, ql, qr, val, op);
        seg[idx] = merge(seg[idx &lt;&lt; 1], seg[idx &lt;&lt; 1 | 1]);
    }
    Node query(i64 idx, i64 l, i64 r, i64 ql, i64 qr)
    {
        if (ql &lt;= l &amp;&amp; r &lt;= qr) return seg[idx];
        push(idx, l, r);
        i64 mid = (l + r) &gt;&gt; 1;
        i64 res = 0;
        if (qr &lt;= mid)
            return query(idx &lt;&lt; 1, l, mid, ql, qr);
        else if (ql &gt; mid)
            return query(idx &lt;&lt; 1 | 1, mid + 1, r, ql, qr);
        else
            return merge(query(idx &lt;&lt; 1, l, mid, ql, qr), query(idx &lt;&lt; 1 | 1, mid + 1, r, ql, qr));
    }
    void build(const vint &amp;a)
    {
        build(1, 1, n, a);
    }
    void update(i64 l, i64 r, i64 val, i64 op)
    {
        update(1, 1, n, l, r, val, op);
    }
    i64 query(i64 l, i64 r)
    {
        return query(1, 1, n, l, r).sum % mod;
    }
};
其实主要思想就是懒标记的使用和下传

ACM/算法/线段树Seg/支持区间查询的线段树.content:
引子：线段树是什么
不知道你有没有被某些算法题搞得焦头烂额，例如给你Q次询问求区间和，区间最大最小，区间子段和这些神秘题目，但是现在，他们都将变成板子题！
线段树是一种二叉树结构,其实作用是可以快速修改和查询,我们先从支持查询的线段数开始
线段树思想

线段树通过将一段区间不断二分，直到分解成单个节点的元素，然后通过合并子区间的信息从而得到父区间的结果，将区间问题变成 分治合并问题

实现
一颗完整的静态线段树需要进行

建树
合并
查询

这些操作
维护信息
根据题目的意义，我们的节点可能维护的信息是不一样的

区间和(sum)
区间最值(max / min)
区间最大子段和 (sum,lmax,rmax,tmax)
一般这些信息都被维护在一个结构体节点下


我们接下来的演示都以 区间子段和 为例子进行演示

struct Node{
	i64 sum,lmax,rmax,tmax;
}
这个表示我们每个节点保存的信息是这个区间的区间和，区间前缀最大值，区间后缀最大值，区间子段最大值
合并策略
在有了维护信息之后我们就需要进行确定合并策略，不同的题目有不同的合并策略
确定合并策略的思考点主要是去寻思两个区间的信息怎么通过一些手段变成他们合并后的信息
下面给出一些合并策略



                  Tip





区间和

res.sum = L.sum + R.sum;

区间最大/最小值

res.max = max(L.max,R.max);
res.min = min(L.min,R.min);

区间最大子段和

res.sum = L.sum + R.sum;
res.lmax = max(L.lmax,L.sum + R.lmax);
res.rmax = max(R.rmax,L.rmax + R.sum);
res.tmax = max({
	L.tmax,
	R.tmax,
	L.rmax + R.lmax
});



我们的写法则是：
Node merge(const Node &amp;L, const Node &amp;R)
{
	Node res;
	res.sum = L.sum + R.sum;
	res.lmax = max(L.lmax, L.sum + R.lmax);
	res.rmax = max(R.rmax, R.sum + L.rmax);
	res.tmax = max({L.tmax, R.tmax, L.rmax + R.lmax});
}
建树
做好了一切的准备后我们便可以开始建树
在建树的时候，我们主要用数组模拟树，同时使用位运算优化建树过程，递归的构建整棵树

vector&lt;Node&gt; seg;
i64 n;
// 建树需要开四倍空间
Seg(i64 n): n(n),seg(n * 4 + 4){}

void build(i64 idx, i64 l, i64 r, const vint &amp;v)
{
	if (l == r) {
		i64 val = v[l];
		seg[idx] = {val, val, val, val};
		return;
	}
	i64 mid = (l + r) &gt;&gt; 1;
	build(idx &lt;&lt; 1, l, mid, v);
	build(idx &lt;&lt; 1 | 1, mid + 1, r, v);
	seg[idx] = merge(seg[idx &lt;&lt; 1], seg[idx &lt;&lt; 1 | 1]);
}
建树的时间复杂度为O(n)
查询
当查询到[ql,qr]区间时候：

若当前节点 [l,r] 完全在区间 [ql,qr] 时，直接返回
若有交叉，则递归到左右子区间
再合并左右结果

Node query(i64 idx, i64 l, i64 r, i64 ql, i64 qr)
{
	if (ql &lt;= l &amp;&amp; r &lt;= qr) return seg[idx];
	i64 mid = (l + r) &gt;&gt; 1;
	if (qr &lt;= mid) {
		return query(idx &lt;&lt; 1, l, mid, ql, qr);
	}
	else if (ql &gt; mid) {
		return query(idx &lt;&lt; 1 | 1, mid + 1, r, ql, qr);
	}
	else {
		return merge(query(idx &lt;&lt; 1, l, mid, ql, qr), query(idx &lt;&lt; 1 | 1, mid + 1, r, ql, qr));
	}
}
则整个树就建立完成了，这是最基本的静态查询线段树,线段树的区间查询是O(\log n)
struct Seg
{
    struct Node
    {
        i64 sum, lmax, rmax, tmax;
    };
    i64 n;
    vector&lt;Node&gt; seg;
    Seg(i64 n): n(n), seg(4 * n + 4, Node()) { }
    //
    Node merge(const Node &amp;L, const Node &amp;R)
    {
        Node res;
        res.sum = L.sum + R.sum;
        res.lmax = max(L.lmax, L.sum + R.lmax);
        res.rmax = max(R.rmax, R.sum + L.rmax);
        res.tmax = max({L.tmax, R.tmax, L.rmax + R.lmax});
    }
    void build(i64 idx, i64 l, i64 r, const vint &amp;v)
    {
        if (l == r) {
            i64 val = v[l];
            seg[idx] = {val, val, val, val};
            return;
        }
        i64 mid = (l + r) &gt;&gt; 1;
        build(idx &lt;&lt; 1, l, mid, v);
        build(idx &lt;&lt; 1 | 1, mid + 1, r, v);
        seg[idx] = merge(seg[idx &lt;&lt; 1], seg[idx &lt;&lt; 1 | 1]);
    }
    Node query(i64 idx, i64 l, i64 r, i64 ql, i64 qr)
    {
        if (ql &lt;= l &amp;&amp; r &lt;= qr) return seg[idx];
        i64 mid = (l + r) &gt;&gt; 1;
        if (qr &lt;= mid) {
            return query(idx &lt;&lt; 1, l, mid, ql, qr);
        }
        else if (ql &gt; mid) {
            return query(idx &lt;&lt; 1 | 1, mid + 1, r, ql, qr);
        }
        else {
            return merge(query(idx &lt;&lt; 1, l, mid, ql, qr), query(idx &lt;&lt; 1 | 1, mid + 1, r, ql, qr));
        }
    }
};

ACM/算法/贪心.content:
