string largeadd(string&amp; a, string&amp; b)
{
    if (a.size() &lt;= b.size()) swap(a, b);
    int p = 0;
    for (size_t i = 0; i &lt; b.size(); i++) {
        int ai = a[a.size() - i - 1] - &#039;0&#039;;
        int bi = b[b.size() - i - 1] - &#039;0&#039;;
        int sum = ai + bi + p;
        if (sum &gt;= 10) {
            p = 1;
            sum -= 10;
        } else p = 0;
        a[a.size() - 1 - i] = sum + &#039;0&#039;;
    }
    for (size_t i = b.size(); i &lt; a.size(); i++) {
        int ai = a[a.size() - i - 1] - &#039;0&#039;;
        if (ai == &#039;9&#039; &amp;&amp; p == 1) {
            a[a.size() - i - 1] = &#039;0&#039;;
        } else {
            a[a.size() - i - 1] = ai + p + &#039;0&#039;;
            p = 0;
        }
    }
    if (p == 1) a.insert(a.begin(), &#039;1&#039;);
    return a;
}
2 高精度减法

与加法类似，主要是注意借位与进位的不同
负数的处理

string largemin(string a, string b)
{
    int flag = 0;
    if (b.size() &gt;= a.size()&amp;&amp; b &gt;= a) {
        swap(a, b);
        flag = 1;
    }
    int p = 0;
    for (size_t i = 0; i &lt; b.size(); i++) {
        int ai = a[a.size() - 1 - i] - &#039;0&#039;;
        int bi = b[b.size() - 1 - i] - &#039;0&#039;;
        int diff = ai - bi - p;
        if (diff &lt; 0) {
            p = 1;
            diff += 10;
        } else p = 0;
        a[a.size() - i - 1] = diff + &#039;0&#039;;
    }
    for (size_t i = b.size(); i &lt; a.size(); i++) {
        int ai = a[a.size() - i - 1] - &#039;0&#039;;
        if (ai == 0 &amp;&amp; p == 1) {
            a[a.size() - i - 1] = &#039;9&#039;;
        } else {
            a[a.size() - i - 1] = ai - p + &#039;0&#039;;
            p = 0;
        }
    }
    while (*a.begin() == &#039;0&#039; &amp;&amp; a.size() &gt; 1)
        a.erase(a.begin());
    if (flag) a.insert(a.begin(), &#039;-&#039;);
    return a;
}
3 高精度乘法



                  Tip




对于乘法来说，高精度的最佳计算思维就是将两个数拆分，用一个数的个十百位依次去乘以另一个数
拿我们常用的，主要的步骤有以下几点：

字符串化数字，倒置字符串
两位相乘，计算结果与储存位数
