    cin &gt;&gt; n;
    vector&lt;i64&gt; res(2 * n + 1);
    i64 idx = 1;
    for (i64 i = n; i &gt;= 1; i--) {
        if (i % 2 == 0) {
            res[idx] = i;
            res[idx + i] = i;
            idx++;
        }
    }
    idx = n / 2 + 1;
    for (i64 i = n; i &gt;= 1; i--) {
