SRE入门/Go语言/HTTP开发/HttpTest.content:
回忆我们编写的Handler
func healthz(w http.ResponseWriter,r *http.Request)
Handler 通过 r 读取请求，通过 w 写出响应。
httptest.NewRecorder() 创建一个实现了 http.ResponseWriter 的响应记录器，将 Handler 写出的状态码、响应头和响应体保存在内存中；httptest.NewRequest() 则构造供服务端处理的 HTTP 请求。因此，测试可以直接调用 Handler，不必先监听端口。
// 位于 net/http/httptest 包中，通过 httptest.NewRequest 调用。
func NewRequest(method string, target string, body io.Reader) *http.Request
第一个参数是 HTTP 方法，第二个参数是请求目标（如 /target），第三个参数是请求体。请求体需要是实现了 io.Reader 接口的值；没有请求体时可以传 nil。例如：
strings.NewReader(`{&quot;name&quot;:&quot;demo&quot;}`)         // 输入为 string
bytes.NewReader([]byte(`{&quot;name&quot;:&quot;demo&quot;}`))  // 输入为 []byte
这两个函数返回的值都实现了 io.Reader，可以作为请求体参数；不能直接把 string 或 []byte 传给 NewRequest 的第三个参数。io.Reader 是接口，不是方法。
下面是一个简单实例:
package main

import (
    &quot;encoding/json&quot;
    &quot;net/http&quot;
    &quot;net/http/httptest&quot;
    &quot;testing&quot;
)

func TestHealthz(t *testing.T) {
    // 1. 准备请求和响应记录器
    req := httptest.NewRequest(http.MethodGet, &quot;/healthz&quot;, nil)
    rec := httptest.NewRecorder()

    // 2. 执行被测代码
    healthz(rec, req)

    // 3. 检查响应状态
    if rec.Code != http.StatusOK {
        t.Fatalf(&quot;status = %d, want %d; body = %s&quot;,
            rec.Code, http.StatusOK, rec.Body.String())
    }

    // 4. 检查响应头
    if got := rec.Header().Get(&quot;Content-Type&quot;); got != &quot;application/json&quot; {
        t.Errorf(&quot;Content-Type = %q, want application/json&quot;, got)
    }

    // 5. 解析并检查 JSON 内容
    var body struct {
        Status string `json:&quot;status&quot;`
    }

    if err := json.Unmarshal(rec.Body.Bytes(), &amp;body); err != nil {
        t.Fatalf(&quot;decode response: %v&quot;, err)
    }

    if body.Status != &quot;ok&quot; {
        t.Errorf(&quot;status field = %q, want ok&quot;, body.Status)
    }
}



                  Tip




直接调用 healthz(rec, req) 会绕过路由匹配：即使请求路径是 /abc，当前 healthz 仍会执行，因为它本身不检查路径。要把路由匹配也纳入测试，可以这样写：
router := http.NewServeMux()
router.HandleFunc(&quot;/healthz&quot;, healthz)

req := httptest.NewRequest(http.MethodGet, &quot;/healthz&quot;, nil)
rec := httptest.NewRecorder()

router.ServeHTTP(rec,req)
这样就是通过router，由它决定调用哪个 Handler。



一些需要注意的点
反序列化不会自动清空旧结构体。
对当前 encoding/json 的普通结构体解析，JSON 中缺失的字段保留原值，因此复用解析变量可能让错误响应通过测试。
因此，每次解析独立响应时应使用新的变量。函数的命名返回变量（例如 func(...) (got Target)）也会在每次调用时重新初始化为零值。
例如，已有 Name: &quot;demo&quot;、Addr: &quot;localhost:8080&quot; 的结构体，解析 {&quot;name&quot;:&quot;updated&quot;} 后只会更新 Name，Addr 仍保留原值。解析 {} 不会清空这些字段；解析 {&quot;name&quot;:&quot;&quot;} 才会把 Name 设为空字符串。在当前 encoding/json 中，null 对普通字符串、整数等字段不产生修改，不能用它清零。
测试需要验证接口行为和状态变化
用创建响应返回的 ID 构造路径，后续始终操作同一资源，并检查响应 ID 一致。PUT 后再次 GET，才能确认更新确实写入；DELETE 后检查 204、空响应体，再 GET 检查 404。
测试也需要隔离和清晰的失败信息
独立场景从明确的初始数据开始；使用全局状态时暂不并行运行这些场景。辅助函数加 t.Helper()；后续步骤依赖的条件失败时用 t.Fatalf，可以继续检查的字段差异用 t.Errorf。
每个请求都使用新的 Recorder，断言和错误日志必须检查当前请求对应的 Recorder。发送 DELETE 后若误检查上一次 GET 的 Recorder，就会把之前的 200 当作删除响应。
请求经过注册了 GET /target/{id} 的 ServeMux 后，路由器会填入 PathValue(&quot;id&quot;)。仅构造 /target/1 的请求再直接调用 Handler，不会自动得到这个路径参数；直接测试 Handler 时需要用 req.SetPathValue(&quot;id&quot;, &quot;1&quot;) 显式设置。
一个简单实例
下面是基于当前 sentinel-go Handler 和共享变量的串行 CRUD 测试示例，需要与项目代码同包使用。它验证成功流程，不代表并发请求或所有错误输入均已覆盖。当前创建接口约定返回 200。
package main

import (
	&quot;encoding/json&quot;
	&quot;net/http&quot;
	&quot;net/http/httptest&quot;
	&quot;strconv&quot;
	&quot;strings&quot;
	&quot;testing&quot;
)

func CheckCode(rec *httptest.ResponseRecorder, needCode int, t *testing.T) {
	t.Helper()
	if rec.Code != needCode {
		t.Errorf(&quot;status = %d,want %d,body = %s&quot;,
			rec.Code, needCode, rec.Body.String())
	}
}

func CheckHeader(rec *httptest.ResponseRecorder, needHeader string, t *testing.T) {
	t.Helper()
	if got := rec.Header().Get(&quot;Content-Type&quot;); got != needHeader {
		t.Errorf(&quot;Content-Type = %s,want %s&quot;, got, needHeader)
	}
}

func TestHealthz(t *testing.T) {

	router := http.NewServeMux()
	router.HandleFunc(&quot;/healthz&quot;, healthz)

	req := httptest.NewRequest(http.MethodGet, &quot;/healthz&quot;, nil)
	rec := httptest.NewRecorder()

	router.ServeHTTP(rec, req)

	CheckCode(rec, http.StatusOK, t)
	CheckHeader(rec, &quot;application/json&quot;, t)

	var body struct {
		Status string `json:&quot;status&quot;`
	}

	if err := json.Unmarshal(rec.Body.Bytes(), &amp;body); err != nil {
		t.Fatalf(&quot;decode response: %v&quot;, err)
	}

	if body.Status != &quot;ok&quot; {
		t.Errorf(&quot;status field = %q, want ok&quot;, body.Status)
	}
}

func TestHealthzMethodNotAllowed(t *testing.T) {
	router := http.NewServeMux()
	router.HandleFunc(&quot;/healthz&quot;, healthz)

	req := httptest.NewRequest(http.MethodPost, &quot;/healthz&quot;, nil)
	rec := httptest.NewRecorder()

	router.ServeHTTP(rec, req)

	CheckCode(rec, http.StatusMethodNotAllowed, t)
}

func TestCreateAndGetTarget(t *testing.T) {
	mu.Lock()
	targets = make(map[int]Target)
	globalId = 0
	mu.Unlock()

	router := http.NewServeMux()
	router.HandleFunc(&quot;POST /target&quot;, addTarget)
	router.HandleFunc(&quot;GET /target/{id}&quot;, getTarget)
	router.HandleFunc(&quot;PUT /target/{id}&quot;, updateTarget)
	router.HandleFunc(&quot;DELETE /target/{id}&quot;, deleteTarget)

	// == create ==

	createReq := httptest.NewRequest(
		http.MethodPost,
		&quot;/target&quot;,
		strings.NewReader(`{&quot;name&quot;:&quot;demo&quot;,&quot;address&quot;:&quot;localhost:8080&quot;}`),
	)
	createReq.Header.Set(&quot;Content-Type&quot;, &quot;application/json&quot;)

	createRec := httptest.NewRecorder()

	router.ServeHTTP(createRec, createReq)

	CheckCode(createRec, http.StatusOK, t)
	CheckHeader(createRec, &quot;application/json&quot;, t)

	checkTarget := func(rec *httptest.ResponseRecorder) (got Target) {
		t.Helper()
		if err := json.Unmarshal(rec.Body.Bytes(), &amp;got); err != nil {
			t.Fatalf(&quot;decode response: %v&quot;, err)
		}
		return
	}

	created := checkTarget(createRec)

	if created.Id &lt;= 0 {
		t.Fatalf(&quot;created id = %d, want positive id&quot;, created.Id)
	}

	if created.Name != &quot;demo&quot; || created.Addr != &quot;localhost:8080&quot; {
		t.Errorf(&quot;wrong result,body = %s&quot;, createRec.Body.String())
	}

	// == GET : 1 ==

	path := &quot;/target/&quot; + strconv.Itoa(created.Id)

	getReq := httptest.NewRequest(
		http.MethodGet,
		path,
		nil,
	)
	getRec := httptest.NewRecorder()
	router.ServeHTTP(getRec, getReq)

	CheckCode(getRec, http.StatusOK, t)
	CheckHeader(getRec, &quot;application/json&quot;, t)
	geted := checkTarget(getRec)

	if geted.Id != created.Id {
		t.Fatalf(&quot;GET id = %d, want %d&quot;, geted.Id, created.Id)
	}

	if geted.Name != &quot;demo&quot; || geted.Addr != &quot;localhost:8080&quot; {
		t.Errorf(&quot;wrong result,body = %s&quot;, getRec.Body.String())
	}

	// == PUT ==

	putReq := httptest.NewRequest(
		http.MethodPut,
		path,
		strings.NewReader(`{&quot;name&quot;:&quot;updated&quot;,&quot;address&quot;:&quot;localhost:9090&quot;}`),
	)
	putRec := httptest.NewRecorder()

	router.ServeHTTP(putRec, putReq)

	CheckCode(putRec, http.StatusOK, t)
	CheckHeader(putRec, &quot;application/json&quot;, t)

	putres := checkTarget(putRec)

	if putres.Id != created.Id {
		t.Fatalf(&quot;PUT id = %d, want %d&quot;, putres.Id, created.Id)
	}

	if putres.Name != &quot;updated&quot; || putres.Addr != &quot;localhost:9090&quot; {
		t.Errorf(&quot;wrong result,body = %s&quot;, putRec.Body.String())
	}

	// == GET : 2 ==

	reGetReq := httptest.NewRequest(
		http.MethodGet,
		path,
		nil,
	)
	reGetRec := httptest.NewRecorder()

	router.ServeHTTP(reGetRec, reGetReq)

	CheckCode(reGetRec, http.StatusOK, t)
	CheckHeader(reGetRec, &quot;application/json&quot;, t)
	reGet := checkTarget(reGetRec)

	if reGet.Id != created.Id {
		t.Fatalf(&quot;GET id = %d, want %d&quot;, reGet.Id, created.Id)
	}

	if reGet.Name != &quot;updated&quot; || reGet.Addr != &quot;localhost:9090&quot; {
		t.Errorf(&quot;wrong result,body = %s&quot;, reGetRec.Body.String())
	}

	// == DELETE ==
	deleteReq := httptest.NewRequest(
		http.MethodDelete,
		path,
		nil,
	)
	deleteRec := httptest.NewRecorder()

	router.ServeHTTP(deleteRec, deleteReq)
	CheckCode(deleteRec, http.StatusNoContent, t)

	if deleteRec.Body.Len() != 0 {
		t.Errorf(&quot;DELETE body = %q, want empty&quot;, deleteRec.Body.String())
	}

	// == GET : 3 ==

	rreGetReq := httptest.NewRequest(
		http.MethodGet,
		path,
		nil,
	)
	rreGetRec := httptest.NewRecorder()

	router.ServeHTTP(rreGetRec, rreGetReq)

	CheckCode(rreGetRec, http.StatusNotFound, t)
}

SRE入门/Go语言/HTTP开发/MemoryStore分层.content:
MemoryStore的分层主要是将数据库中的需要的操作都抽象分离开，在原理的设计中，Handler操作全局状态的 Targets 和 mux。但是显然这样会出现或多或少的问题
比如当我们进行并发测试等，虽然我们有锁了，但是对于连续的两个测试来说，如果只靠锁，无法解决串行污染和数据污染的问题，我们需要在每次测试前初始化数据让测试得以进行，这同时就直觉性的引出我们需要将对数据的操作 “抽象” 出来的思想，于是我们遍设计了 MemoryStore分层这样的工程架构
什么架构?
package main

import (
	&quot;errors&quot;
	&quot;sync&quot;
)

var (
	ErrTargetNotFound = errors.New(&quot;target not found&quot;)
	ErrInvalidTarget  = errors.New(&quot;name and address are required&quot;)
)

type MemoryStore struct {
	targets map[int]Target
	nextID  int
	mu      sync.Mutex
}

func InitMemoryStore() *MemoryStore {
	return &amp;MemoryStore{
		targets: make(map[int]Target),
		nextID:  0,
	}
}

func (store *MemoryStore) Create(req TargetRequest) Target {
	store.mu.Lock()
	defer store.mu.Unlock()
	store.nextID += 1
	store.targets[store.nextID] = Target{
		Id:   store.nextID,
		Name: req.Name,
		Addr: req.Addr,
	}
	return store.targets[store.nextID]
}

func (store *MemoryStore) List() []Target {
	store.mu.Lock()
	list := make([]Target, 0, len(store.targets))
	for _, target := range store.targets {
		list = append(list, target)
	}
	store.mu.Unlock()
	return list
}

func (store *MemoryStore) Get(id int) (Target, error) {
	store.mu.Lock()
	res, ok := store.targets[id]
	store.mu.Unlock()
	if !ok {
		err := errors.New(&quot;invalid user id&quot;)
		return res, err
	}
	return res, nil
}

func (store *MemoryStore) Update(id int, req TargetRequest) (Target, error) {
	store.mu.Lock()
	defer store.mu.Unlock()
	target, ok := store.targets[id]

	if !ok {
		return target, ErrTargetNotFound
	}

	if req.Name == &quot;&quot; || req.Addr == &quot;&quot; {
		return target, ErrInvalidTarget
	}
	store.targets[id] = Target{
		Name: req.Name,
		Addr: req.Addr,
		Id:   target.Id,
	}
	return store.targets[id], nil
}

func (store *MemoryStore) Delete(id int) error {
	store.mu.Lock()
	defer store.mu.Unlock()
	_, ok := store.targets[id]
	if !ok {
		err := errors.New(&quot;invaild target&quot;)
		return err
	}
	delete(store.targets, id)
	return nil
}
这是store.go的源码，我们可以注意到所有之前的全局变量被抽象成了 MemoryStore 的 struct,同时对这些数据的读写操作都被统一抽象为了这个 struct 的成员业务函数
Store的注入
现在我们将基础的CRUD抽象成为了业务函数并且抽象出 MemoryStore 后，对于主函数中的Handler也要进行修改，随后将 Store 注入这些 Handler 中
这里做的就是，也将 Handler 抽象成一个 Struct，并且里面的成员含有 *MemoryStore ,随后这个 Handler 就“拥有了” 这个 store 并且能够访问其方法
type Handler struct {
	store *MemoryStore
}
同时我们重构了 main 函数，将注入过程抽离成 run 函数
func run() error {
	store := InitMemoryStore()
	mux := NewRouter(store)
	server := &amp;http.Server{
		Addr:              &quot;:9090&quot;,
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,  // 客户端传入Header限制
		ReadTimeout:       8 * time.Second,  // 服务器读取整个请求时间限制
		WriteTimeout:      10 * time.Second, // 服务器写入响应时间限制
		IdleTimeout:       30 * time.Second, // HTTP keep-alive
	}

	serverErr := make(chan error, 1)

	ctx, stop := signal.NotifyContext(
		context.Background(),
		os.Interrupt,
		syscall.SIGTERM,
	)
	defer stop()

	go func() {
		serverErr &lt;- server.ListenAndServe()
	}()

	select {
	case err := &lt;-serverErr:
		if err != nil &amp;&amp; !errors.Is(err, http.ErrServerClosed) {
			return fmt.Errorf(&quot;listen and serve: %w&quot;, err)
		}
		log.Println(&quot;Server Normal exit&quot;)
		return nil
	case &lt;-ctx.Done():
		shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()

		err := server.Shutdown(shutdownCtx)
		if err != nil {
			return fmt.Errorf(&quot;shutdown server: %w&quot;, err)
		}
		log.Println(&quot;get system stop signal,exit Http server&quot;)
		return nil
	}
}



                  Tip




main 中的 select 语句，主要是表示两种不同的退出方式，在 ctx 中是优雅退出，在 serverErr 中是接收到错误后的处理，详细可以看 HTTP优雅退出流程

SRE入门/Go语言/HTTP开发/PostgreSQL最小持久化.content:
对于一个后端程序，需要链接数据库，而CRUD也有在数据库层面上进行的内容，本文的目标就是，不仅仅将 HTTP 的CRUD局限在内存与 go 语言操作中，而是去操作PostgreSQL
核心接口
实际上，完成对 PostgreSQL 的操作，我们需要使用 pgx 和 database/sql
主要使用的接口是
query := `SELECT id, name, address
		  FROM targets
		WHERE id = $1`
row := store.db.QueryRowContext(ctx, query, id)
err := row.Scan(&amp;target.Id, &amp;target.Name, &amp;target.Addr)
	if errors.Is(err, sql.ErrNoRows) {
		return Target{}, ErrTargetNotFound
	}
其中 query 就是我们的SQL语句，需要注意的是SQL语句这里需要写返回值和使用 $1,$2来代表传入的参数
下面的 QueryRowContext 则表示进行一次SQL操作，ctx是一个中断 context , query 表示要查询的 SQL 语句，同时后面接需要传入的参数
这个函数会返回一个 sql.Row ,即这个row，我们需要使用用它的方法 Scan 来将 SQL 中返回的数据存入内存中，注意，如果SQL没有找到对应的行，这会返回一个 sql.ErrNoRows，我们需要接住它并且返回一个对外的显式错误ErrTargetNotFound
测试
测试这里首先需要注意的是，我们需要在测试这里单独打开和数据库的链接，注册store
func registerStore(t *testing.T) *PostgresStore {
	t.Helper()
	if os.Getenv(&quot;RUN_POSTGRES_TESTS&quot;) != &quot;1&quot; {
		t.Skip(&quot;set RUN_POSTGRES_TESTS=1 to run PostgreSQL integration tests&quot;)
	}
	dsn := os.Getenv(&quot;DATABASE_URL&quot;)
	if dsn == &quot;&quot; {
		t.Fatal(&quot;DATABASE_URL is required when PostgreSQL tests are enabled&quot;)
	}
	db, err := sql.Open(&quot;pgx&quot;, dsn)
	if err != nil {
		t.Fatalf(&quot;Open Error: %v&quot;, err)
	}
	t.Cleanup(func() {
		if err := db.Close(); err != nil {
			t.Errorf(&quot;close database: %v&quot;, err)
		}
	})
	store := NewPostgresStore(db)
	ctxWithTime, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()
	if err := store.db.PingContext(ctxWithTime); err != nil {
		t.Fatalf(&quot;Connect Error : %v&quot;, err)
	}
	return store
}
这里需要我们注意的一点就是，我们为什么需要用 pingContext 来完成测试?实际原因是，sql.open 没问题相当与说明和数据库的初始化链接这个 “门” 没有问题，我们需要实际去 ping 一次才能知道究竟能否正常操作SQL
同时，通过 t.clean() 注册清理也是我们需要注意的，clean会按照先来后执行的方式，在测试退出的时候依次执行，所以我们需要在 open() 后立刻注册关闭数据库的清理，在调用 create 后立刻注册对数据库中测试数据的清理

SRE入门/Go语言/接口.content:
语法
我们使用 type [接口名称] interface{} 来声明一个接口
type Sayer interface {
	Say(messge string) error
}
当我们需要实现一个接口的继承的时候，我们可以直接实现这个接口里的方法
type Dog struct {
    name string
}

func (dog *Dog)Say(messge string) error{
	fmt.println(dog.name + &quot;说：&quot; + messge)
	return nil
}

// 在实现的时候我们可以
var sa Sayer
d := &amp;Dog{&quot;name&quot;}
sa = d
sa.Say()       //接口可以调用d的方法了，此时我们实现了接口
工程约束

命名约定：

单一方法接口：以er结尾，例如Reader,Writer
不要预先定义：接口应该由使用者定义，而不是生产者定义


接口设计：越小越好

Go语言鼓励组合小接口而不是去创建一个庞大的接口


接受接口，返回结构体

在设计一个函数的时候，应该尽量接受接口，以提高函数的通用性
函数应该返回具体的结构体



接口能干什么
下面我们用一个简单的需求展现interface的功能
需求描述：多渠道告警系统

我们的任务是编写一个告警小程序。这个程序需要支持多种通知方式（如邮件、短信），并且要能够轻松扩展新的通知方式（比如以后要加一个“钉钉告警”），而不需要修改核心的业务逻辑代码。



接口定义:
定义一个名为 Notifier 的接口，它必须包含一个方法：Notify(message string) error


具体实现
实现两个结构体，并让它们都满足 Notifier 接口：



EmailNotifier: 结构体里包含一个 Address 字段。调用 Notify 时，打印：“向邮件地址 [xxx] 发送了消息：[内容]”。
SMSNotifier: 结构体里包含一个 PhoneNumber 字段。调用 Notify 时，打印：“向手机号 [xxx] 发送了短信：[内容]”。


核心业务逻辑（关键点）
编写一个函数 SendAlerts：

参数：接受一个 Notifier 接口的切片（[]Notifier）和一条消息字符串。
功能：循环遍历切片，调用每个元素的 Notify 方法。



在 main 函数中：

创建一个包含一个 EmailNotifier 和一个 SMSNotifier 的切片。
调用 SendAlerts 函数，把这个切片传进去。
进阶思考:


如果现在想增加一个 WeChatNotifier，你是否需要修改 SendAlerts 函数的代码？


参考：
package main

import (
	&quot;fmt&quot;
)

type Notifier interface {
	Notify(message string) error
}

type EmailNotifier struct {
	Address string
}

type SMSNotifier struct {
	Phonenumber string
}

func (emi *EmailNotifier) Notify(message string) error {
	fmt.Println(&quot;向邮件地址&quot; + emi.Address + &quot;发送了信息:&quot; + message)
	return nil
}

func (sms *SMSNotifier) Notify(message string) error {
	fmt.Println(&quot;向手机号&quot; + sms.Phonenumber + &quot;发送了信息&quot; + message)
	return nil
}

func SendAlerts(notify []Notifier) error {
	for _, n := range notify {
		n.Notify(&quot;Testmessage&quot;)
	}
	return nil
}

// 新增WeChatNotifier
type WeChatNotifier struct {
	WechatID string
}

func (wec *WeChatNotifier) Notify(message string) error {
	fmt.Println(&quot;向微信号:&quot; + wec.WechatID + &quot;推送：&quot; + message)
	return nil
}

func main() {
	nois := []Notifier{&amp;EmailNotifier{&quot;test1&quot;}, &amp;SMSNotifier{&quot;test2&quot;}}
	SendAlerts(nois)
	nois = append(nois, &amp;WeChatNotifier{&quot;test3&quot;})
	SendAlerts(nois)
}

SRE入门/Go语言/文件读写.content:
文件读写
小文件
如果你能确定你读取的文件或者你写入的数据量，那么你可以使用 os 提供的 ReadFile 和 WriteFile 函数
// 文件读入
data,err := os.ReadFile(&quot;example.txt&quot;)
if err != nil{
	log.Fatal(err)
}
fmt.Println(string(data))

// 文件写出
content := []byte(&quot;Hello Go&quot;)
err := os.WriteFile(&quot;out.txt&quot;,content,0644)
if err != nil{
	log.Fatal(err)
}
逐行或按块处理

使用 bufio.Scanner 逐行读取

file , err := os.Open(&quot;large_file.txt&quot;)
if err != nil{
	log.Fatal(err)
}
defer file.Close() //注意关闭文件

scanner := bufio.NewScanner(file)
for scanner.Scan(){
	string s = scanner.Text()
	// 处理
}
if err := scanner.Err(); err != nil{
	log.Fatal(err)
}
文件的写入操作
如果你需要对文件进行更精细的控制（比如追加内容），需要使用 os.OpenFile。
追加内容到文件
// O_APPEND: 追加模式, O_CREATE: 如果不存在则创建, O_WRONLY: 只写模式
file, err := os.OpenFile(&quot;log.txt&quot;, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
if err != nil {
    log.Fatal(err)
}
defer file.Close()

if _, err := file.WriteString(&quot;New log entry\n&quot;); err != nil {
    log.Fatal(err)
}
使用 bufio.Writer 提高性能
在频繁进行小量写入时，使用缓冲区可以显著减少系统调用，提升性能。
writer := bufio.NewWriter(file)
writer.WriteString(&quot;Buffered string&quot;)
writer.Flush() // 必须调用 Flush 确保数据从缓冲区写入磁盘

SRE入门/技巧/GO语言下pprf的分析.content:
对于go语言的pprf分析我们有两种情况，一个是针对长期开启的服务进行探测，还有一种是针对脚本进行分析
针对服务型
我们可以在代码中使用 net/http/pprof 包。你只需要在代码中匿名引入，它会自动在 8080（或其他你定义的）端口开启一个 /debug/pprof 路由。
// 在main函数中启动
go func() {
   http.ListenAndServe(&quot;localhost:6060&quot;, nil)
    }()
这样go会在6060端口下打开一个网页(虽然很简陋)，访问http://localhost:6060/debug/pprof/就可以看到这样一个的分析

脚本
对于脚本和一些简单go程序，会运行一段时间直接退出，这个时候就不适合打开端口监控了，我们可以直接在脚本中插入埋点
package main

import (
    &quot;os&quot;
    &quot;runtime/pprof&quot;
    &quot;runtime&quot;
    &quot;log&quot;
)

func main() {
    // --- CPU Profile ---
    cpuFile, err := os.Create(&quot;cpu.prof&quot;)
    if err != nil {
        log.Fatal(err)
    }
    pprof.StartCPUProfile(cpuFile)
    defer pprof.StopCPUProfile()

    // 运行你的脚本逻辑
    runScriptLogic()

    // --- Memory Profile ---
    memFile, err := os.Create(&quot;mem.prof&quot;)
    if err != nil {
        log.Fatal(err)
    }
    defer memFile.Close()

    // 显式运行一次 GC，确保内存数据准确
    runtime.GC() 
    if err := pprof.WriteHeapProfile(memFile); err != nil {
        log.Fatal(err)
    }
}

func runScriptLogic() {
    // 模拟耗时或内存密集操作
    sum := 0
    for i := 0; i &lt; 1000000; i++ {
        sum += i
    }
}
这个时候我们运行结束后会发现目录下多了cpu.prof 和 mem.prof 文件，我们使用pprf就可以进行分析：
go tool pprof cpu.prof
更推荐的测试方法
如果我们需要测试的内容可以封装为一个函数，那么使用 Go 的测试工具链进行性能分析是最简单、最专业的做法， 不需要在业务代码里写任何 pprof 代码
我们需要编写一个benchmark文件
package main

import &quot;testing&quot;

func BenchmarkMyTask(b *testing.B) {
    for i := 0; i &lt; b.N; i++ {
        runScriptLogic() // 调用你要分析的函数
    }
}
然后通过 test 工具链对整个程序进行测试并生成分析
go test -bench . -cpuprofile cpu.prof -memprofile mem.prof
最后通过pprf进行分析
go tool pprof -http=:8080 cpu.prof // 在8080端口打开网页，需要安装Graphviz

SRE入门/网络/HTTP-Method.content:
Method 是什么
先建立最基础的模型。从语义层面看，一个 HTTP Request 可以先关注：
Method + Path + Header + Body
其中 Method 可以先理解为客户端希望对目标资源执行的动作。例如 GET /targets/1 表示请求读取 /targets/1 所标识的资源。
HTTP Method 和 CRUD 有常见对应关系，但两者并非严格等价。例如 POST 也可以表示提交任务或触发处理，并不一定创建资源。
GET        → Read
POST       → Create（常见用法之一）
PUT/PATCH  → Update
DELETE     → Delete
GET
GET 表示获取资源的当前表示。例如 GET /targets 通常读取 Target 集合，而 GET /targets/1 读取 ID 为 1 的单个 Target。
假设服务器中存在：
Target: 1
name = &quot;google&quot;
address = &quot;google.com&quot;

Target: 2
name = &quot;github&quot;
address = &quot;github.com&quot;
请求 GET /targets 时，服务器可以返回 JSON 数组：
HTTP/1.1 200 OK
Content-Type: application/json

[
  {
    &quot;id&quot;: 1,
    &quot;name&quot;: &quot;google&quot;,
    &quot;address&quot;: &quot;google.com&quot;
  },
  {
    &quot;id&quot;: 2,
    &quot;name&quot;: &quot;github&quot;,
    &quot;address&quot;: &quot;github.com&quot;
  }
]
如果请求 GET /targets/1，则只返回 ID 为 1 的资源；资源不存在时通常返回 404 Not Found。
GET 是安全且幂等的方法：“安全”表示客户端请求的目标不是修改服务器状态；“幂等”表示多次相同请求的预期效果与一次相同。
POST
POST 表示客户端向目标资源提交数据，请服务器按照该资源的语义进行处理。在本项目中，它用于向集合创建一个新 Target：
POST /targets
Content-Type: application/json

{
  &quot;name&quot;: &quot;google&quot;,
  &quot;address&quot;: &quot;google.com&quot;
}
创建成功后通常返回 201 Created 和创建后的资源，也可以通过 Location 响应头告诉客户端新资源的 URI。
设计资源风格的 API 时，一般使用 POST /targets，而不是 POST /createTarget，因为 Method 已经表达了操作语义。不过这是一种常见 API 设计方式，不是 HTTP 协议强制规定。
POST 通常不是幂等方法：重复发送同一个创建请求，可能创建多个不同资源。
PUT
PUT 通常表示：

用客户端提供的完整表示替换目标资源的当前表示。

例如客户端发送：
PUT /targets/1
Content-Type: application/json

{
  &quot;name&quot;: &quot;google&quot;,
  &quot;address&quot;: &quot;google.com&quot;
}
则服务器中的资源会被完整替换为：
{
  &quot;id&quot;: 1,
  &quot;name&quot;: &quot;google&quot;,
  &quot;address&quot;: &quot;google.com&quot;
}
PUT 是幂等方法：多次发送相同 PUT 请求，其预期服务器状态与发送一次相同。在 sentinel-go 当前约定中，更新不存在的 ID 返回 404 Not Found；HTTP 标准也允许某些 API 使用 PUT 创建指定 URI 的资源，因此具体行为需要在接口契约中写清楚。
PATCH
PATCH 也表示更新。与 PUT 的完整替换不同，PATCH 请求体描述要应用到资源的一组局部修改，因此通常只提供需要变化的字段。
例如客户端发送：
PATCH /targets/1
Content-Type: application/json

{
  &quot;name&quot;: &quot;bing&quot;
}
更新后的资源可能是：
{
  &quot;id&quot;: 1,
  &quot;name&quot;: &quot;bing&quot;,
  &quot;address&quot;: &quot;google.com&quot;
}
PUT 和 PATCH 成功后可以返回更新后的资源和 200 OK，也可以在不返回正文时使用 204 No Content；具体选择应保持一致并写入接口契约。PATCH 不保证天然幂等，其幂等性取决于补丁格式和操作语义。
DELETE
DELETE 用于删除目标资源。当客户端发送 DELETE /targets/{id} 时，就是请求删除该 ID 对应的 Target；成功且不返回正文时通常使用 204 No Content，资源不存在时通常返回 404 Not Found。
DELETE 是幂等方法。这里的“幂等”指多次相同请求的预期服务器状态与执行一次相同，而不是要求每次响应状态码完全相同；第一次删除可能返回 204，再次删除可能返回 404。
安全性与幂等性速查









































Method安全幂等当前项目中的常见用途GET是是查询 TargetPOST否通常否创建 TargetPUT否是完整替换 TargetPATCH否不一定局部修改 TargetDELETE否是删除 Target
