编程语言/C++/基础语法/程序结构流程.content:
4 程序流程结构
C/C++支持的三种程序运行结构：顺序结构，选择结构，循环结构

顺序结构:类似于Python的运行结构，程序按顺序执行，不发生跳转
选择结构:依据条件是否满足，有选择的执行相应功能
循环结构:依据条件是否满足，循环多次执行某段代码

4.1 选择结构
4.1.1 if语句
作用: 执行满足条件的语句
其主要有三种形式：

单行格式if语句
多行格式if语句
多条件的if语句


单行格式if语句:if(条件){ 条件满足执行的语句 }


示例:
int main()
{
    //单行if结构
    //让用户输入一个分数，如果大于600，则输出&quot;恭喜&quot;
    //1. 用户输入分数
    int score = 0;
    cout &lt;&lt; &quot;请输入一个分数&quot;&lt;&lt;endl;
    cin &gt;&gt; score ;
    //2. 打印用户分数
    cout &lt;&lt; &quot;您的分数为:&quot;&lt;&lt;score&lt;&lt;endl;
    //3.判断
    if(score &gt; 600) //if条件语法后没有分号！！！
    {
        cout&lt;&lt;&quot;恭喜&quot;&lt;&lt;endl;
    }

    system(&quot;pause&quot;);
    return(0);
}



                  Important




if条件后面不要加分号




多行格式if语句：if(条件){ 条件为真执行的语句 }else{ 条件不满足执行的语句 }


示例:
int main()
{
    //多行格式if
    //提示用户输入分数，如果分数大于600，则输出&quot;恭喜&quot;，若没有大于600，则输出&quot;别放弃&quot;
    int score = 0;
    cout &lt;&lt;&quot;请输入一个分数&quot;&lt;&lt;endl;
    cin &gt;&gt; score;
    cout &lt;&lt; &quot;您的分数为&quot;&lt;&lt; score &lt;&lt;endl;
    //执行判断
    if(score &gt; 600) //大于600的情况
    {
        cout &lt;&lt; &quot;恭喜&quot;&lt;&lt;endl;
    }
    else //小于600的情况
    {
        cout &lt;&lt; &quot;别放弃&quot;&lt;&lt;endl;
    }
    system(&quot;pause&quot;);
    return(0);
}

多条件的if语句:if(条件1){满足条件1执行的语句}else if(条件2){满足条件2执行的语句}... else{都不满足执行的语句}


int main()
{
    //多条件的if语句
    //1.输入分数
    int score = 0;
    cout &lt;&lt; &quot;请输入一个分数&quot;&lt;&lt;endl;
    cin &gt;&gt; score;
    cout &lt;&lt; &quot;您的分数是&quot; &lt;&lt; score &lt;&lt; endl;
    //2.条件判断(大于600)
    if (score &gt;= 600)
    {
        cout &lt;&lt; &quot;恭喜&quot;&lt;&lt;endl;
    }
    else if (score &gt;= 500)//这里不能写(500 &lt; score &lt; 600)
    {
        cout &lt;&lt; &quot;别放弃&quot;&lt;&lt;endl;
    }
    else if (score &gt;= 400)
    {
        cout &lt;&lt; &quot;还可以&quot;&lt;&lt;endl;
    }
    else
    {
        cout &lt;&lt; &quot;别摆烂辣！&quot;&lt;&lt;endl;
    }

    system(&quot;pause&quot;);
    return(0);
}
嵌套if语句：在if语句中再嵌套一个if语句
案例要求:

在上个代码的基础上，根据分数再细化
大于700为特等，大于650为一等，大于600为优秀

int main()
{
    //多条件的if语句
    //1.输入分数
    int score = 0;
    cout &lt;&lt; &quot;请输入一个分数&quot;&lt;&lt;endl;
    cin &gt;&gt; score;
    cout &lt;&lt; &quot;您的分数是&quot; &lt;&lt; score &lt;&lt; endl;
    if (score &gt;= 600)
    {
        cout &lt;&lt; &quot;恭喜&quot;&lt;&lt;endl;
        if (score &gt;= 700) //嵌套的if语句
        {
            cout &lt;&lt; &quot;特等&quot;&lt;&lt;endl;
        }
        else if (score &gt;= 650)
        {
            cout &lt;&lt; &quot;一等&quot;&lt;&lt;endl;
        }
        else
        {
            cout &lt;&lt; &quot;优秀&quot;&lt;&lt;endl;
        }
    }
    else if (score &gt;= 500)//这里不能写(500 &lt; score &lt; 600)
    {
        cout &lt;&lt; &quot;别放弃&quot;&lt;&lt;endl;
    }
    else if (score &gt;= 400)
    {
