**练习案例：**水仙花数

水仙花数是一个三位数，它的每个位上的三次幂之和等于它本身
例：1^3^+5^3^+3^3^=153

//注意：要有#include&lt;cmath&gt;
int main()
{
    //定义初始值，其中fnum3,2,1分别代表百十个位，这个三位数要和初始值fnum相等
    int fnum1 = 0;
    int fnum2 = 0;
    int fnum3 = 1;
    float fnumt = 0;
    int fnum = 100;
    do
    {

        fnum++;
        fnum1++;
        //三位数输出，个十百位分别输出
        if (fnum1 - 1  == 9)
        {
        fnum1 = 0;
        fnum2++;
        }
        if (fnum2 - 1 == 9)
        {
        fnum2 = 0;
        fnum3++;
        }
        if (fnum3 - 1 == 9)
        {
            fnum3 = 0;
        }

        fnumt = pow(fnum1,3) + pow(fnum2,3) + pow(fnum3,3);
        if ( fnumt == fnum)
        {
            cout &lt;&lt;&quot;水仙花&quot;&lt;&lt; fnum &lt;&lt; endl;
        }
        // cout &lt;&lt; fnum &lt;&lt; endl;
        // cout &lt;&lt; fnumt &lt;&lt; endl;
        // cout &lt;&lt;&quot;个位&quot;&lt;&lt; fnum1 &lt;&lt; endl;
        // cout &lt;&lt;&quot;十位&quot; &lt;&lt;fnum2 &lt;&lt; endl;
        // cout &lt;&lt;&quot;百位&quot; &lt;&lt;fnum3 &lt;&lt; endl;

    } while (fnum &lt; 1000);
    system(&quot;pause&quot;);
    return(0);

}



                  Important




如何获取一个三位数的个十百位？

例:153
个位:153%10 = 3    对数字取模于10可以获得个位
十位:153/10 = 15 \to15 % 10 = 5  C++中整除只留整数部分即 (153/10)%10
百位:153/100 = 1




示例：
int main()
{
    int num = 100;
    do{
        num++;
        if(num == pow(num%10,3)+pow((num/10)%10,3)+pow(num/100,3))
        {
            cout &lt;&lt; num &lt;&lt;endl;
        }
    }while(num &lt; 999);

    system(&quot;pause&quot;);
    return(0);
}
